<section class="hero" id="<?php echo esc_attr( $root_id ); ?>" data-hero>
  <div class="container">
    <div class="hero__layout">
      <div class="hero__content">
        <div class="hero__wrap hero__wrap_top" data-hero-panel>
          <?php echo platejka_section_image( $section_data['background_image'] ?? 0, 'large', array( 'class' => 'hero__image', 'alt' => '', 'loading' => 'eager', 'decoding' => 'async', 'fetchpriority' => 'high', 'sizes' => '(max-width: 767px) 100vw, 864px', 'style' => 'height:100%;object-fit:cover', 'data-hero-image' => '' ) ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?>
          <?php echo platejka_section_image( $section_data['blur_image'] ?? 0, 'large', array( 'class' => 'hero__blur', 'alt' => '', 'loading' => 'eager', 'decoding' => 'async', 'sizes' => '(max-width: 767px) 100vw, 864px', 'style' => 'object-fit:cover', 'data-hero-blur' => '' ) ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?>
          <?php if ( ! empty( $section_data['badge'] ) ) : ?><p class="hero__badge" data-hero-copy><?php echo esc_html( $section_data['badge'] ); ?></p><?php endif; ?>
          <h1 class="hero__title" data-hero-copy><span class="hero__title-primary"><?php echo platejka_heading_text( $title['primary'] ?? '' ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?></span><span class="hero__title-secondary"><?php echo platejka_heading_text( $title['secondary'] ?? '' ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?></span></h1>
          <?php if ( ! empty( $section_data['subtitle'] ) ) : ?><p class="hero__subtitle" data-hero-copy><?php echo esc_html( $section_data['subtitle'] ); ?></p><?php endif; ?>
          <ul class="list-reset hero__items" data-hero-copy><?php foreach ( $items as $item ) : ?><li class="hero__item"><span class="hero__item-title"><?php echo esc_html( $item['title'] ?? '' ); ?></span><span class="hero__item-content"><?php echo esc_html( $item['text'] ?? '' ); ?></span></li><?php endforeach; ?></ul>
          <?php if ( ! empty( $section_data['info'] ) ) : ?><p class="hero__info" data-hero-copy><?php echo esc_html( $section_data['info'] ); ?></p><?php endif; ?>
        </div>

        <ul class="list-reset hero__trust" data-hero-cards>
          <li class="hero__trust-card hero__trust-card_experience"><div class="hero__trust-years" aria-label="<?php echo esc_attr( $experience['value'] ?? '' ); ?>"><?php echo platejka_section_image( $experience['left_image'] ?? 0, 'thumbnail', array( 'alt' => '', 'loading' => 'eager', 'sizes' => '22px' ) ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?><span aria-hidden="true"><?php echo esc_html( $experience['value'] ?? '' ); ?></span><?php echo platejka_section_image( $experience['right_image'] ?? 0, 'thumbnail', array( 'alt' => '', 'loading' => 'eager', 'sizes' => '22px' ) ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?></div><p class="hero__trust-caption"><?php echo esc_html( $experience['label'] ?? '' ); ?></p></li>
          <?php foreach ( array( 'registry' => $registry, 'association' => $association ) as $variant => $trust_item ) :
			$link       = is_array( $trust_item['link'] ?? null ) ? $trust_item['link'] : array();
			$link_class = 'registry' === $variant ? 'ui-link--overlay' : 'ui-link--inverse';
			?>
            <li class="hero__trust-card hero__trust-card_<?php echo esc_attr( $variant ); ?>"><p class="hero__trust-title"><?php echo platejka_heading_text( $trust_item['title'] ?? '' ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?></p><?php echo platejka_section_image( $trust_item['image'] ?? 0, 'medium', array( 'class' => 'hero__trust-decor hero__trust-decor_' . $variant, 'alt' => '', 'loading' => 'eager', 'sizes' => '161px' ) ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?><?php if ( ! empty( $link['url'] ) ) : ?><a class="ui-link <?php echo esc_attr( $link_class ); ?> hero__trust-link" href="<?php echo esc_url( $link['url'] ); ?>"<?php echo ! empty( $link['target'] ) ? ' target="' . esc_attr( $link['target'] ) . '" rel="noopener"' : ''; // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?>><?php echo esc_html( $link['title'] ?? '' ); ?></a><?php elseif ( ! empty( $link['title'] ) ) : ?><span class="ui-link <?php echo esc_attr( $link_class ); ?> hero__trust-link"><?php echo esc_html( $link['title'] ); ?></span><?php endif; ?></li>
          <?php endforeach; ?>
        </ul>
      </div>

