        <div class="hero-calculator__body"><h2 class="hero-calculator__title"><?php echo esc_html( $calculator_labels['summary'] ?? '' ); ?></h2><div class="ui-tabs hero-calculator__currencies" aria-label="<?php echo esc_attr( $calculator_labels['currency'] ?? '' ); ?>"><span class="hero-calculator__indicator" data-currency-indicator aria-hidden="true"></span><?php foreach ( array( 'CNY' => 'cn-flag.png', 'USD' => 'usa-flag.png' ) as $currency => $flag ) : ?><button class="ui-tab hero-calculator__currency<?php echo 'CNY' === $currency ? ' is-active' : ''; ?>" type="button" data-currency="<?php echo esc_attr( $currency ); ?>" aria-pressed="<?php echo 'CNY' === $currency ? 'true' : 'false'; ?>"><img class="hero-calculator__flag" src="img/<?php echo esc_attr( $flag ); ?>" width="20" height="20" alt=""><?php echo esc_html( $currency ); ?></button><?php endforeach; ?></div><div class="hero-calculator__field"><label class="hero-calculator__label" for="<?php echo esc_attr( $amount_id ); ?>"><?php echo esc_html( $calculator_labels['amount'] ?? '' ); ?></label><div class="hero-calculator__amount-wrap"><input class="ui-amount-input hero-calculator__amount" id="<?php echo esc_attr( $amount_id ); ?>" name="amount" type="number" min="1" step="1" inputmode="numeric" value="100000" data-role="amount" required><span class="hero-calculator__symbol" data-role="currency-symbol" aria-hidden="true">¥</span></div></div><dl class="hero-calculator__results"><?php foreach ( array( 'official_rate' => 'official-rate', 'conversion_rate' => 'conversion-rate', 'commission' => 'commission', 'total' => 'grand-total' ) as $label_key => $role ) : ?><div class="hero-calculator__result-row<?php echo 'total' === $label_key ? ' hero-calculator__result-row_total' : ''; ?>"><dt><?php echo esc_html( $calculator_labels[ $label_key ] ?? '' ); ?></dt><dd><output data-role="<?php echo esc_attr( $role ); ?>">0 ₽</output></dd></div><?php endforeach; ?></dl><button class="ui-button hero-calculator__submit" type="submit"><?php echo esc_html( $calculator_labels['request'] ?? '' ); ?></button><p class="hero-calculator__note"><img src="img/Shield-Check.svg" width="24" height="24" alt=""><?php echo esc_html( $calculator_data['note'] ?? '' ); ?></p></div>
      </form>
    </div>
  </div>
  <dialog class="contact-dialog" data-contact-dialog aria-labelledby="<?php echo esc_attr( $dialog_title_id ); ?>"><div class="contact-dialog__content"><button class="btn-reset contact-dialog__close" type="button" data-dialog-close aria-label="<?php echo esc_attr( $calculator_labels['close'] ?? '' ); ?>">×</button><h2 class="contact-dialog__title" id="<?php echo esc_attr( $dialog_title_id ); ?>"><?php echo esc_html( $calculator_labels['dialog'] ?? '' ); ?></h2><p class="contact-dialog__text"><?php echo esc_html__( 'Параметры расчёта готовы для заявки.', 'platejka_rework' ); ?></p><p class="contact-dialog__summary" data-dialog-summary><?php echo esc_html( $calculator_labels['summary_empty'] ?? '' ); ?></p><div data-cf7-mount><?php echo platejka_cf7_form( $calculator_data['form'] ?? 0 ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?></div></div></dialog>
</section>
<script type="application/json" data-calculator-labels-for="<?php echo esc_attr( $root_id ); ?>"><?php echo wp_json_encode( $calculator_labels ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?></script>
